"use client";

import Image from "next/image";
import { FormEvent, useEffect, useState } from "react";
import { QueryClient, QueryClientProvider, useQuery } from "@tanstack/react-query";
import { motion } from "framer-motion";
import { useForm } from "react-hook-form";
import { z } from "zod";
import { zodResolver } from "@hookform/resolvers/zod";
import type { LucideIcon } from "lucide-react";
import { ArrowDown, ArrowRight, Bell, Bot, BookOpen, Building2, CalendarDays, CheckCircle2, ChevronRight, ClipboardList, FlaskConical, GraduationCap, LibraryBig, MapPin, Menu, MonitorSmartphone, Moon, Phone, Play, Quote, Search, Send, ShieldCheck, Sparkles, Trophy, UsersRound, X } from "lucide-react";
import { Button } from "@/components/ui/button";

type Notice = { day: string; month: string; title: string; detail: string; type: string };
type LeadershipContent = { slug: string; name: string; designation: string; message: string; photo_url: string | null; signature_url: string | null; office_hours: string | null; position: number };
type PublicContent = { configured: boolean; settings: Record<string, unknown>; leadership: LeadershipContent[] };
const notices: Notice[] = [
  { day: "08", month: "May", title: "Admission Open for Grade 11 (2081)", detail: "Application open from Baisakh 15 to Jestha 15, 2081", type: "Admission" },
  { day: "02", month: "May", title: "Routine for First Terminal Exam", detail: "Examination starts from Jestha 1, 2081", type: "Academic" },
  { day: "28", month: "Apr", title: "Parent–Teacher Meeting", detail: "Meeting on Baisakh 30, 2081 at 10:00 AM", type: "General" },
];
const nav = ["About", "Academics", "Teachers", "Campus Life", "Notices", "Admissions", "Contact"];
const media = { hero: "/media/nps-hero-gate.png", campus: "/media/nps-campus-building.png", staff: "/media/nps-staff-group.jpg", transport: "/media/nps-transport.png", logo: "/media/nps-logo.png", science: "/media/science-lab.png", sports: "/media/sports-day.png", principal: "/media/principal-placeholder.png", vicePrincipal: "/media/vice-principal-placeholder.png", commandant: "/media/commandant-placeholder.png" };
const admissionSchema = z.object({ student: z.string().min(2, "Enter the student's name"), guardian: z.string().min(2, "Enter the parent or guardian's name"), phone: z.string().min(7, "Enter a valid phone number"), grade: z.string().min(1, "Select an interested grade") });
type AdmissionValues = z.infer<typeof admissionSchema>;

function useNotices() { return useQuery({ queryKey: ["published-notices"], queryFn: async () => notices, staleTime: Infinity }); }
function usePublicContent() { return useQuery({ queryKey: ["public-site-content"], queryFn: async (): Promise<PublicContent> => { const response = await fetch("/api/site-content", { cache: "no-store" }); if (!response.ok) throw new Error("Content service unavailable"); return response.json() as Promise<PublicContent>; }, retry: false, staleTime: 60_000 }); }
function Crest() { return <div className="relative h-12 w-12 shrink-0 overflow-hidden rounded-full border border-white/70 bg-white shadow-sm"><Image src={media.logo} alt="Nepal Police School logo" fill className="object-contain p-0.5" sizes="48px"/></div>; }
function SectionTitle({ eyebrow, title, copy }: { eyebrow: string; title: string; copy?: string }) { return <div className="max-w-2xl"><p className="text-[11px] font-bold uppercase tracking-[.2em] text-sky-700">{eyebrow}</p><h2 className="mt-3 text-3xl font-extrabold leading-tight tracking-tight text-[#06275c] sm:text-4xl">{title}</h2>{copy && <p className="mt-4 text-sm leading-7 text-slate-600">{copy}</p>}</div>; }
function DateTile({ day, month }: { day: string; month: string }) { return <time className="grid h-13 w-13 shrink-0 place-content-center rounded-2xl bg-sky-50 text-center text-[#06275c]"><b className="text-lg leading-none">{day}</b><span className="mt-1 text-[9px] font-bold uppercase">{month}</span></time>; }

export function NpsCampus() { const [client] = useState(() => new QueryClient()); return <QueryClientProvider client={client}><HomePage /></QueryClientProvider>; }

function HomePage() {
  const [menuOpen, setMenuOpen] = useState(false); const [aiOpen, setAiOpen] = useState(false); const [admissionOpen, setAdmissionOpen] = useState(false); const [tourOpen, setTourOpen] = useState(false); const [intro, setIntro] = useState<"checking" | "playing" | "exiting" | "done">("checking"); const noticeQuery = useNotices(); const contentQuery = usePublicContent(); const content = contentQuery.data;
  useEffect(() => { const introKey = "nps-intro-v3-seen"; const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches; const startTimer = window.setTimeout(() => setIntro(reduceMotion || window.sessionStorage.getItem(introKey) ? "done" : "playing"), 0); if (reduceMotion || window.sessionStorage.getItem(introKey)) return () => window.clearTimeout(startTimer); const exitTimer = window.setTimeout(() => setIntro("exiting"), 2500); const doneTimer = window.setTimeout(() => { window.sessionStorage.setItem(introKey, "true"); setIntro("done"); }, 2800); return () => { window.clearTimeout(startTimer); window.clearTimeout(exitTimer); window.clearTimeout(doneTimer); }; }, []);
  if (intro !== "done") return <OpeningIntro stage={intro}/>;
  return <main className="overflow-x-hidden bg-[#f8fbff]">
    <motion.div initial={{ y: -24, opacity: 0 }} animate={{ y: 0, opacity: 1 }} transition={{ duration: .65, delay: .28, ease: [0.22, 1, 0.36, 1] }}><FloatingHeader openMenu={() => setMenuOpen(true)} openAi={() => setAiOpen(true)} navigation={content?.settings.navigation}/></motion.div>
    <CinematicHero openAdmission={() => setAdmissionOpen(true)} hero={content?.settings.hero} />
    <QuickInfo openAi={() => setAiOpen(true)} openAdmission={() => setAdmissionOpen(true)} />
    <AboutAndPrincipal />
    <PremiumLeadership leaders={content?.leadership} />
    <AcademicPrograms />
    <FeatureBand />
    <Stats />
    <CampusLife />
    <FacilitiesAndMap />
    <AchievementWall />
    <JourneyTimeline />
    <NewsAndEvents notices={noticeQuery.data ?? []} />
    <Testimonials />
    <VideoTour open={() => setTourOpen(true)} />
    <AdmissionCta open={() => setAdmissionOpen(true)} />
    <Footer footer={content?.settings.footer} />
    <button className="fixed bottom-6 right-6 z-40 grid h-[60px] w-[60px] place-items-center rounded-full bg-[#1565c0] text-white shadow-[0_16px_34px_rgba(8,74,157,.36)] transition duration-200 hover:scale-105 hover:bg-[#0d55a5] focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-blue-600" onClick={() => setAiOpen(true)} aria-label="Open NPS AI Assistant"><Bot size={28}/></button>
    {menuOpen && <MobileMenu close={() => setMenuOpen(false)} openAi={() => { setMenuOpen(false); setAiOpen(true); }} />}
    {aiOpen && <AiDialog close={() => setAiOpen(false)} />}
    {admissionOpen && <AdmissionDialog close={() => setAdmissionOpen(false)} />}
    {tourOpen && <TourDialog close={() => setTourOpen(false)} />}
  </main>;
}

function OpeningIntro({ stage }: { stage: "checking" | "playing" | "exiting" }) {
  const visible = stage === "playing"; const ease = [0.22, 1, 0.36, 1] as const;
  return <motion.div initial={{ opacity: 0 }} animate={{ opacity: stage === "exiting" ? 0 : 1 }} transition={{ duration: stage === "exiting" ? .3 : .25, ease }} className="fixed inset-0 z-[100] grid place-items-center overflow-hidden bg-[#071423] px-6 text-center text-white"><div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_40%,rgba(21,101,192,.32),transparent_26%),radial-gradient(circle_at_18%_82%,rgba(7,68,155,.28),transparent_25%),radial-gradient(circle_at_83%_18%,rgba(14,92,190,.18),transparent_24%)]"/><motion.span animate={{ x: [0, 26, 0], y: [0, -18, 0], opacity: [.16, .32, .16] }} transition={{ duration: 2.5, repeat: Infinity, ease: "easeInOut" }} className="absolute left-[15%] top-[22%] h-2 w-2 rounded-full bg-sky-300 blur-[1px]"/><motion.span animate={{ x: [0, -24, 0], y: [0, 20, 0], opacity: [.12, .3, .12] }} transition={{ duration: 2.2, repeat: Infinity, ease: "easeInOut" }} className="absolute bottom-[20%] right-[18%] h-3 w-3 rounded-full bg-blue-400 blur-[1px]"/><motion.div animate={{ opacity: stage === "exiting" ? 0 : 1, scale: stage === "exiting" ? 1.05 : 1 }} transition={{ duration: .3, ease }} className="relative"><motion.div initial={{ opacity: 0, scale: .4, rotateY: 360 }} animate={{ opacity: visible ? 1 : 0, scale: visible ? 1 : .4, rotateY: visible ? 0 : 360, y: visible ? [0, -3, 0] : 0 }} transition={{ opacity: { duration: .45, delay: .25, ease }, rotateY: { duration: .75, delay: .25, ease }, scale: { type: "spring", stiffness: 180, damping: 15, delay: .25 }, y: { duration: 1.5, delay: 1.15, repeat: Infinity, ease: "easeInOut" } }} className="relative mx-auto h-34 w-34 drop-shadow-[0_0_28px_rgba(82,162,255,.55)]"><Image src={media.logo} alt="Nepal Police School logo" fill priority className="object-contain" sizes="136px"/></motion.div><motion.p initial={{ opacity: 0, y: 20, letterSpacing: ".32em" }} animate={{ opacity: visible ? 1 : 0, y: visible ? 0 : 20, letterSpacing: visible ? ".22em" : ".32em" }} transition={{ duration: .3, delay: 1.2, ease }} className="mt-8 text-xs font-bold text-sky-200">WELCOME TO</motion.p><motion.h1 initial={{ opacity: 0, y: 20, filter: "blur(8px)" }} animate={{ opacity: visible ? 1 : 0, y: visible ? 0 : 20, filter: visible ? "blur(0px)" : "blur(8px)" }} transition={{ duration: .35, delay: 1.5, ease }} className="mt-4 text-2xl font-extrabold tracking-tight sm:text-3xl">NEPAL POLICE SCHOOL</motion.h1><motion.h2 initial={{ opacity: 0, y: 20, filter: "blur(8px)" }} animate={{ opacity: visible ? 1 : 0, y: visible ? 0 : 20, filter: visible ? "blur(0px)" : "blur(8px)" }} transition={{ duration: .35, delay: 1.6, ease }} className="mt-1 text-lg font-semibold tracking-[.12em] text-blue-100 sm:text-xl">GARUDA, RAUTAHAT</motion.h2></motion.div></motion.div>;
}

function FloatingHeader({ openMenu, openAi, navigation }: { openMenu: () => void; openAi: () => void; navigation?: unknown }) {
  const [megaOpen, setMegaOpen] = useState(false); const [teachersOpen, setTeachersOpen] = useState(false); const [compact, setCompact] = useState(false);
  const customNav = Array.isArray(navigation) ? navigation.filter((item): item is { label: string; href: string } => Boolean(item) && typeof item === "object" && "label" in item && "href" in item && typeof item.label === "string" && typeof item.href === "string") : null;
  const links = customNav?.length ? customNav : nav.map((label) => ({ label, href: label === "Teachers" ? "/teachers" : `#${label.toLowerCase().replaceAll(" ", "-")}` }));
  useEffect(() => { const update = () => setCompact(window.scrollY > 24); update(); window.addEventListener("scroll", update, { passive: true }); return () => window.removeEventListener("scroll", update); }, []);
  const departments = ["English", "Mathematics", "Science", "Nepali", "Social Studies", "Computer Science", "Management", "Physical Education"];
  const academicLinks = [["Primary", "/academics/primary"], ["Secondary", "/academics/secondary"], ["+2 Programs", "/academics/plus-2"], ["Curriculum", "/academics/curriculum"], ["Faculty", "/academics/faculty"], ["Library", "/academics/library"], ["Sports", "/academics/sports"], ["Downloads", "/academics/downloads"]] as const;
  // This legacy client navbar uses in-page anchors and a single internal teacher route together.
  // eslint-disable-next-line @next/next/no-html-link-for-pages
  return <header className="fixed inset-x-0 top-0 z-30 px-4 pt-4 sm:px-7 sm:pt-6"><nav className={`relative mx-auto flex max-w-7xl items-center justify-between rounded-2xl border border-white/50 bg-white/88 px-4 shadow-[0_10px_35px_rgba(0,42,100,.16)] backdrop-blur-xl transition-all duration-300 sm:px-5 ${compact ? "h-[58px]" : "h-[68px]"}`}><a className="flex items-center gap-2.5" href="#home"><Crest/><span><strong className="block text-sm font-extrabold uppercase tracking-tight text-[#06275c]">Nepal Police School</strong><span className="block text-[10px] text-slate-600">Garuda, Rautahat</span></span></a><div className="hidden items-center gap-7 lg:flex">{links.map(item => item.label === "Academics" ? <button className="text-xs font-bold text-[#163d74] transition hover:text-[#1565c0]" onMouseEnter={() => setMegaOpen(true)} onClick={() => setMegaOpen(value => !value)} key={item.label}>Academics +</button> : item.label === "Teachers" ? <a className="text-xs font-bold text-[#163d74] transition hover:text-[#1565c0]" href={item.href} onMouseEnter={() => setTeachersOpen(true)} onFocus={() => setTeachersOpen(true)} key={item.label}>Teachers +</a> : <a className="text-xs font-bold text-[#163d74] transition hover:text-[#1565c0]" href={item.href} key={item.label}>{item.label}</a>)}</div><div className="flex items-center gap-2"><button className="grid h-9 w-9 place-items-center rounded-full text-[#163d74] hover:bg-sky-50" aria-label="Search"><Search size={18}/></button><Button size="sm" className="hidden sm:inline-flex" onClick={openAi}><Bot size={15}/> AI Assistant</Button><button className="grid h-9 w-9 place-items-center rounded-full border border-sky-100 text-[#163d74] lg:hidden" onClick={openMenu} aria-label="Open menu"><Menu size={20}/></button></div>{megaOpen && <div className="absolute left-[28%] top-[58px] hidden w-[520px] rounded-2xl border border-sky-100 bg-white p-6 shadow-2xl lg:block" onMouseLeave={() => setMegaOpen(false)}><div className="grid grid-cols-[.8fr_1.2fr] gap-7"><div className="rounded-xl bg-sky-50 p-4"><GraduationCap className="text-[#1565c0]"/><p className="mt-4 text-sm font-extrabold text-[#06275c]">Explore Academics</p><p className="mt-2 text-xs leading-5 text-slate-600">Programs, faculty, curriculum, resources and student support.</p></div><div className="grid grid-cols-2 gap-y-4 text-xs font-bold text-[#163d74]">{academicLinks.map(([label, href]) => <a className="hover:text-[#1565c0]" href={href} key={label}>{label}</a>)}</div></div></div>}{teachersOpen && <div className="absolute left-[42%] top-[58px] hidden w-[390px] rounded-2xl border border-sky-100 bg-white p-5 shadow-2xl lg:block" onMouseLeave={() => setTeachersOpen(false)} onBlur={(event) => { if (!event.currentTarget.contains(event.relatedTarget)) setTeachersOpen(false); }}><p className="text-[10px] font-bold uppercase tracking-[.16em] text-sky-700">Faculty departments</p><p className="mt-2 text-sm font-extrabold text-[#06275c]">Meet our teaching teams</p><div className="mt-4 grid grid-cols-2 gap-1">{departments.map(department => <a key={department} href={`/teachers?department=${encodeURIComponent(department)}`} className="rounded-lg px-3 py-2 text-xs font-bold text-[#163d74] transition hover:bg-sky-50 hover:text-[#1565c0]">{department}</a>)}</div><a href="/teachers" className="mt-4 inline-flex text-xs font-bold text-sky-700 hover:text-sky-900">View all teachers →</a></div>}</nav></header>;
}

