function PremiumLeadership({ leaders: managedLeaders }: { leaders?: LeadershipContent[] }) {
  const fallbackLeaders = [
    { image: media.principal, name: "Principal name", designation: "Principal", message: "Education is the foundation of every successful life. We are dedicated to nurturing minds, building character, and helping every student grow with confidence and responsibility.", signature: "Principal signature" },
    { image: media.vicePrincipal, name: "Vice Principal name", designation: "Vice Principal", message: "We believe in a holistic education that combines strong academic standards with discipline, creativity, and moral values for every student.", signature: "Vice Principal signature" },
    { image: media.commandant, name: "Commandant name", designation: "Commandant", message: "Discipline is our identity. We prepare students to be responsible citizens and future leaders who serve their community with dignity.", signature: "Commandant signature" },
  ];
  const leaders = managedLeaders?.length ? managedLeaders.map((leader) => ({ image: leader.photo_url || media.principal, name: leader.name, designation: leader.designation, message: leader.message, signature: leader.signature_url || "Signature" })) : fallbackLeaders;
  return <section id="leadership" className="bg-[#f5f9ff] px-5 py-28 lg:px-8"><div className="mx-auto max-w-7xl"><div className="text-center"><p className="text-[11px] font-bold uppercase tracking-[.2em] text-sky-700">Our leadership</p><h2 className="mt-3 text-3xl font-extrabold text-[#06275c] sm:text-4xl">Leadership That Inspires Excellence</h2><p className="mx-auto mt-4 max-w-3xl text-sm leading-7 text-slate-600">Meet the leaders of Nepal Police School Garuda, Rautahat, whose vision, discipline, and commitment guide every student&apos;s journey toward academic excellence, character development, and responsible citizenship.</p></div><div className="mt-12 grid items-stretch gap-6 lg:grid-cols-3">{leaders.map((leader, index) => <motion.article initial={{ opacity: 0, y: 18 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: .2 }} transition={{ duration: .4, delay: index * .08 }} className="group relative grid min-h-[560px] grid-rows-[260px_1fr] overflow-hidden rounded-[1.5rem] bg-white shadow-[0_12px_30px_rgba(11,61,145,.12)] transition duration-300 hover:-translate-y-1 hover:shadow-[0_20px_42px_rgba(11,61,145,.2)]" key={leader.designation}><div className="relative overflow-hidden"><Image src={leader.image} alt={`${leader.designation} of Nepal Police School`} fill unoptimized={leader.image.startsWith("http")} className="object-cover object-top transition duration-500 group-hover:scale-105" sizes="(max-width: 1024px) 100vw, 33vw"/><div className="absolute inset-0 bg-gradient-to-t from-[#06275c]/28 to-transparent"/></div><div className="relative flex flex-col p-7"><Crest/><Quote className="absolute right-6 top-5 text-[#f4b400]/20" size={78} fill="currentColor"/><p className="mt-5 text-[11px] font-bold uppercase tracking-[.15em] text-[#1565c0]">{leader.designation}</p><h3 className="mt-1 text-xl font-extrabold text-[#06275c]">{leader.name}</h3><p className="mt-4 text-sm leading-6 text-slate-600">{leader.message}</p><div className="mt-auto border-t border-sky-100 pt-4"><p className="font-serif text-lg italic text-[#1565c0]">{leader.signature}</p><button className="mt-3 inline-flex items-center gap-2 text-sm font-bold text-[#1565c0]">Read full message <ArrowRight size={15}/></button></div></div></motion.article>)}</div></div></section>;
}

