function NewsAndEvents({ notices }: { notices: Notice[] }) {
  return <section className="bg-white"><div className="mx-auto grid max-w-7xl gap-16 px-5 py-28 lg:grid-cols-[1.1fr_.9fr] lg:px-8"><div id="notices"><SectionTitle eyebrow="Latest news" title="Keep up with campus."/><div className="mt-9 grid gap-4 sm:grid-cols-3">{notices.map((notice,index) => <article className="group border-b border-sky-100 pb-5" key={notice.title}><div className={`h-36 overflow-hidden rounded-2xl ${index===1?"bg-sky-100":"bg-blue-100"}`}><Image src={index===2?media.sports:index===1?media.science:media.hero} alt="Generic news image placeholder managed in CMS" width={500} height={300} className="h-full w-full object-cover transition duration-500 group-hover:scale-105"/></div><p className="mt-4 text-[11px] font-bold uppercase tracking-[.14em] text-sky-700">{notice.type} · {notice.day} {notice.month}</p><h3 className="mt-2 text-sm font-extrabold leading-5 text-[#06275c]">{notice.title}</h3><button className="mt-3 inline-flex items-center gap-1 text-xs font-bold text-[#1565c0]">Read more <ArrowRight size={13}/></button></article>)}</div></div><div id="events" className="border-l-0 border-sky-100 pl-0 lg:border-l lg:pl-12"><SectionTitle eyebrow="Upcoming events" title="Join the community."/><div className="mt-8 space-y-0">{[["25","May","Inter-House Football Tournament","8:00 AM · School Ground"],["01","Jun","Science Exhibition 2081","10:00 AM · Science Lab"],["15","Jun","Annual Sports Meet","9:00 AM · School Ground"]].map(([day,month,title,info],index) => <div className="relative grid grid-cols-[58px_1fr] gap-4 border-l border-sky-200 pb-8 pl-6 last:pb-0" key={title}><span className="absolute -left-1.25 top-0 h-2.5 w-2.5 rounded-full bg-[#1565c0]"/><DateTile day={day} month={month}/><div><p className="text-[11px] font-bold text-sky-700">{info}</p><h3 className="mt-1 text-base font-extrabold text-[#06275c]">{title}</h3><button className="mt-3 inline-flex items-center gap-1 text-xs font-bold text-[#1565c0]">Register <ArrowRight size={13}/></button></div></div>)}</div></div></div></section>;
}

function Testimonials() { const quotes = [["Parent of an NPS student","NPS has helped our child become more confident, focused, and excited to learn every day."],["NPS student","The teachers challenge us while making sure everyone feels supported and included."],["NPS alumnus","The values I learned at NPS continue to shape how I approach every opportunity."]]; const [active,setActive] = useState(0); const [person,quote] = quotes[active]; return <section className="mx-auto max-w-7xl px-5 py-28 lg:px-8"><div className="grid overflow-hidden rounded-[2rem] bg-[#eaf5ff] md:grid-cols-[.75fr_1.25fr]"><div className="relative min-h-64"><Image src={active===1?media.science:media.sports} alt="Generic NPS community testimonial media placeholder" fill className="object-cover" sizes="(max-width: 768px) 100vw, 35vw"/></div><div className="p-8 sm:p-12"><p className="text-[11px] font-bold uppercase tracking-[.16em] text-sky-700">Community voices</p><Quote className="mt-6 text-[#f4b400]" size={36} fill="currentColor"/><motion.p key={quote} initial={{opacity:0,y:10}} animate={{opacity:1,y:0}} className="mt-4 max-w-xl text-xl font-medium leading-8 text-[#06275c]">“{quote}”</motion.p><p className="mt-6 text-sm font-extrabold text-[#06275c]">{person}</p><p className="mt-1 text-xs tracking-[.18em] text-[#f4b400]">★★★★★</p><div className="mt-8 flex gap-2">{quotes.map((_,index)=><button className={`h-2.5 rounded-full transition ${active===index?"w-8 bg-[#1565c0]":"w-2.5 bg-sky-200"}`} onClick={()=>setActive(index)} aria-label={`Show testimonial ${index+1}`} key={index}/>)}</div></div></div></section>; }

function VideoTour({ open }: { open: () => void }) { return <section id="virtual-tour" className="relative overflow-hidden bg-[#061f4e] py-28 text-white"><Image src={media.sports} alt="Generic sports day video poster placeholder" fill className="object-cover opacity-45" sizes="100vw"/><div className="absolute inset-0 bg-[#061f4e]/65"/><div className="relative mx-auto flex max-w-7xl flex-col items-start justify-between gap-8 px-5 sm:flex-row sm:items-center lg:px-8"><div><p className="text-[11px] font-bold uppercase tracking-[.2em] text-sky-200">Virtual campus</p><h2 className="mt-3 text-4xl font-extrabold">Experience NPS from anywhere.</h2><p className="mt-4 max-w-lg text-sm leading-7 text-blue-100">Take a closer look at our campus, learning spaces, and student life.</p></div><button onClick={open} className="grid h-[72px] w-[72px] place-items-center rounded-full border border-white/70 bg-white/15 text-white backdrop-blur transition hover:scale-105" aria-label="Play campus tour"><Play size={28} fill="currentColor"/></button></div></section>; }

function AdmissionCta({ open }: { open: () => void }) { return <section id="admissions" className="mx-auto max-w-7xl px-5 py-22 lg:px-8"><div className="grid overflow-hidden rounded-[2rem] bg-[linear-gradient(110deg,#0b5eba,#1565c0)] text-white md:grid-cols-[1.2fr_.8fr]"><div className="px-8 py-11 sm:px-12"><p className="text-[11px] font-bold uppercase tracking-[.18em] text-sky-100">Admissions open for 2082</p><h2 className="mt-3 text-3xl font-extrabold">Your Future Starts Here.</h2><p className="mt-3 max-w-xl text-sm leading-6 text-blue-100">Connect with our admissions team for verified requirements, application guidance, and a personal campus visit.</p><div className="mt-8 flex flex-wrap gap-3"><Button variant="light" onClick={open}>Apply today <ArrowRight size={16}/></Button><button className="rounded-xl border border-white/50 px-5 py-3 text-sm font-bold transition hover:bg-white/10">Book campus visit</button><button className="rounded-xl border border-white/30 px-4 py-3 text-sm font-bold text-sky-100 hover:bg-white/10">Download prospectus</button></div></div><div className="relative min-h-62"><Image src={media.science} alt="Generic student learning image placeholder for admission CTA" fill className="object-cover" sizes="(max-width: 768px) 100vw, 35vw"/><div className="absolute inset-0 bg-[#06275c]/15"/></div></div></section>; }

function Footer({ footer: _footer }: { footer?: unknown }) { return <footer id="contact" className="bg-[#041e4a] px-5 py-14 text-white lg:px-8"><div className="mx-auto grid max-w-7xl gap-10 sm:grid-cols-2 lg:grid-cols-[1.5fr_1fr_1fr_1fr_1fr]"><div><div className="flex items-center gap-3"><Crest/><div><h2 className="text-sm font-extrabold uppercase">Nepal Police School</h2><p className="mt-1 text-xs text-blue-200">Garuda, Rautahat</p></div></div><p className="mt-5 text-xs leading-6 text-blue-100"><MapPin className="mr-1 inline" size={14}/> Garuda Municipality, Ward No. 7, Rautahat, Nepal<br/><Phone className="mr-1 inline" size={14}/> +977-55-XXXXXX<br/>info@npsgaruda.edu.np</p></div>{[["Explore","About school","Academics","Campus life","Notices"],["Admissions","Apply now","Forms & downloads","Scholarships","FAQs"],["Information","Contact","Privacy policy","Terms & conditions","Sitemap"]].map(([heading,...links]) => <div key={heading}><h3 className="text-sm font-extrabold">{heading}</h3>{links.map(link => <a className="mt-3 block text-xs text-blue-100 transition hover:text-white" href="#home" key={link}>{link}</a>)}</div>)}<div><h3 className="text-sm font-extrabold">Newsletter</h3><p className="mt-3 text-xs leading-5 text-blue-100">Receive school news and announcements.</p><div className="mt-4 flex rounded-xl bg-white p-1"><input className="min-w-0 flex-1 bg-transparent px-2 text-xs text-[#06275c] outline-none" placeholder="Email address"/><button className="grid h-8 w-8 place-items-center rounded-lg bg-[#1565c0]" aria-label="Subscribe"><ArrowRight size={15}/></button></div></div></div><p className="mx-auto mt-12 max-w-7xl border-t border-blue-300/20 pt-4 text-center text-[11px] text-blue-200">© 2025 Nepal Police School, Garuda, Rautahat. All rights reserved.</p></footer>; }

function MobileMenu({ close, openAi }: { close: () => void; openAi: () => void }) { return <motion.aside initial={{x:"100%"}} animate={{x:0}} transition={{duration:.22}} className="fixed inset-y-0 right-0 z-50 w-[min(360px,92vw)] bg-[#06275c] p-6 text-white shadow-2xl"><div className="flex items-center justify-between"><Crest/><button onClick={close} aria-label="Close menu"><X/></button></div><p className="mt-6 text-lg font-extrabold">Nepal Police School</p><p className="mt-1 text-xs text-sky-200">Garuda, Rautahat</p><nav className="mt-8 grid gap-1">{nav.map(item => <a className="rounded-lg px-3 py-3 text-sm font-bold hover:bg-blue-800" href={`#${item.toLowerCase().replaceAll(" ", "-")}`} onClick={close} key={item}>{item}</a>)}</nav><Button className="mt-6 w-full" onClick={openAi}><Bot size={16}/> Ask NPS AI</Button></motion.aside>; }

function AiDialog({ close }: { close: () => void }) { const [messages,setMessages] = useState([{sender:"bot",text:"Hello! I’m NPS AI Assistant. How can I help you today?"}]); const [value,setValue] = useState(""); function ask(text:string){const query=text.trim();if(!query)return;const response=query.toLowerCase().includes("admission")?"Admissions information is available in the Admissions section. Please contact the school office for verified dates and eligibility details.":"I don't have verified information about that.";setMessages(current=>[...current,{sender:"user",text:query},{sender:"bot",text:response}]);setValue("");} function submit(event:FormEvent){event.preventDefault();ask(value);} return <div className="fixed inset-0 z-50 grid place-items-center bg-blue-950/55 p-4"><motion.section initial={{opacity:0,scale:.96}} animate={{opacity:1,scale:1}} className="w-full max-w-md overflow-hidden rounded-2xl bg-white shadow-2xl"><header className="flex items-center justify-between bg-[#06275c] px-5 py-4 text-white"><span className="flex items-center gap-2 font-extrabold"><Bot size={20}/> NPS AI Assistant</span><button onClick={close} aria-label="Close assistant"><X/></button></header><div className="h-72 space-y-3 overflow-y-auto bg-sky-50 p-4">{messages.map((message,index)=><div className={`max-w-[84%] rounded-2xl px-3 py-2 text-xs leading-5 ${message.sender==="user"?"ml-auto bg-sky-600 text-white":"bg-white text-[#06275c]"}`} key={index}>{message.text}</div>)}</div><div className="flex flex-wrap gap-2 px-4 py-3">{["Admissions","Academics","Facilities","Notices"].map(suggestion=><button className="rounded-full border border-sky-200 px-3 py-1 text-[10px] font-bold text-sky-700" onClick={()=>ask(suggestion)} key={suggestion}>{suggestion}</button>)}</div><form className="flex gap-2 border-t border-sky-100 p-4" onSubmit={submit}><input className="min-w-0 flex-1 rounded-full border border-sky-200 px-4 py-2 text-sm outline-sky-500" value={value} onChange={event=>setValue(event.target.value)} placeholder="Type your message…"/><Button aria-label="Send" size="sm"><Send size={16}/></Button></form></motion.section></div>; }

function TourDialog({ close }: { close: () => void }) { return <div className="fixed inset-0 z-50 grid place-items-center bg-blue-950/70 p-4"><motion.section initial={{opacity:0,scale:.96}} animate={{opacity:1,scale:1}} className="relative w-full max-w-4xl overflow-hidden rounded-2xl bg-[#061f4e] shadow-2xl"><button className="absolute right-4 top-4 z-10 grid h-9 w-9 place-items-center rounded-full bg-white/20 text-white backdrop-blur" onClick={close} aria-label="Close campus tour"><X/></button><div className="relative aspect-video"><Image src={media.hero} alt="Campus tour poster placeholder managed through CMS" fill className="object-cover opacity-80"/><div className="absolute inset-0 grid place-items-center bg-[#061f4e]/35"><button className="grid h-20 w-20 place-items-center rounded-full bg-white text-[#1565c0] shadow-xl" aria-label="Play tour video"><Play size={32} fill="currentColor"/></button></div></div><div className="p-6 text-white"><p className="text-[11px] font-bold uppercase tracking-[.16em] text-sky-200">Campus tour</p><h2 className="mt-2 text-2xl font-extrabold">Your NPS tour video will play here.</h2><p className="mt-2 text-sm leading-6 text-blue-100">This is a CMS-ready video placeholder. Add verified NPS drone footage or a campus film when available.</p></div></motion.section></div>; }

function AdmissionDialog({ close }: { close: () => void }) { const form=useForm<AdmissionValues>({resolver:zodResolver(admissionSchema),defaultValues:{student:"",guardian:"",phone:"",grade:""}});const [submitted,setSubmitted]=useState(false);return <div className="fixed inset-0 z-50 grid place-items-center bg-blue-950/55 p-4"><motion.section initial={{opacity:0,scale:.96}} animate={{opacity:1,scale:1}} className="relative w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl"><button className="absolute right-4 top-4 text-[#06275c]" onClick={close} aria-label="Close admission form"><X/></button><p className="text-[11px] font-bold uppercase tracking-[.14em] text-sky-700">Admissions</p><h2 className="mt-2 text-2xl font-extrabold text-[#06275c]">Start an enquiry</h2><p className="mt-2 text-xs leading-5 text-slate-600">The school will confirm all official requirements and next steps.</p>{submitted?<p className="mt-6 rounded-xl bg-emerald-50 p-4 text-sm font-medium text-emerald-800">Thank you. Your enquiry has been recorded locally for this demo.</p>:<form className="mt-6 grid gap-4" onSubmit={form.handleSubmit(()=>setSubmitted(true))}>{[["student","Student name"],["guardian","Parent / guardian name"],["phone","Phone number"]].map(([name,label])=><label className="grid gap-1 text-xs font-bold text-[#06275c]" key={name}>{label}<input className="rounded-lg border border-sky-200 p-2.5 font-normal outline-sky-500" {...form.register(name as keyof AdmissionValues)}/>{form.formState.errors[name as keyof AdmissionValues]&&<small className="text-red-600">{form.formState.errors[name as keyof AdmissionValues]?.message}</small>}</label>)}<label className="grid gap-1 text-xs font-bold text-[#06275c]">Interested grade<select className="rounded-lg border border-sky-200 p-2.5 font-normal outline-sky-500" {...form.register("grade")}><option value="">Select grade</option>{[6,7,8,9,10,11].map(grade=><option value={`Grade ${grade}`} key={grade}>Grade {grade}</option>)}</select>{form.formState.errors.grade&&<small className="text-red-600">{form.formState.errors.grade.message}</small>}</label><Button type="submit">Submit enquiry <ArrowRight size={16}/></Button></form>}</motion.section></div>; }
